package com.nexus.access.backend.place;
import java.util.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.data.domain.Page; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.validation.annotation.Validated; import org.springframework.web.bind.annotation.*;
/** Mutating endpoints will require authorized municipality/admin roles in Phase 4. */
@Validated @RestController @RequestMapping("/api/places") public class PlaceController {private final PlaceService service; public PlaceController(PlaceService s){service=s;} @GetMapping public Page<PlaceResponseDTO> list(@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) int size,@RequestParam(defaultValue="name") String sort){return service.list(page,size,sort);}@GetMapping("/nearby") public List<NearbyPlaceResponseDTO> nearby(@RequestParam @DecimalMin("-90") @DecimalMax("90") double latitude,@RequestParam @DecimalMin("-180") @DecimalMax("180") double longitude,@RequestParam @DecimalMin("0.01") @DecimalMax("50000") double radius){return service.nearby(latitude,longitude,radius);}@GetMapping("/{id}") public PlaceResponseDTO get(@PathVariable UUID id){return service.get(id);}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','MUNICIPALITY')") public ResponseEntity<PlaceResponseDTO> create(@Valid @RequestBody CreatePlaceRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','MUNICIPALITY')") public PlaceResponseDTO update(@PathVariable UUID id,@Valid @RequestBody UpdatePlaceRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);}}
